/* Annual preset translations generated by generate-chronicle-decks.mjs. */
(function(root){'use strict';const ui=root.DuelUITranslations;const names={"blackwing-2009":["Blackwing Gale · 2009","BF・疾風 · 2009"],"cat-gladiator-2009":["Cat Gladiator Beast · 2009","猫剣闘獣 · 2009"],"cat-synchro-2009":["Cat Synchro · 2009","猫シンクロ · 2009"],"frog-ftk-2010":["Frog Cannon · 2010","ガエル・キャノン · 2010"],"blackwing-2010":["Blackwing Whirlwind · 2010","BF・旋風 · 2010"],"herald-2010":["Herald of Perfection · 2010","神光の宣告者 · 2010"],"agents-2011":["Agent Fairy · 2011","代行天使 · 2011"],"junk-doppel-2011":["Junk Doppel · 2011","ジャンクドッペル · 2011"],"six-samurai-2011":["Legendary Six Samurai · 2011","真六武衆 · 2011"],"inzektor-2012":["Inzektor · 2012","甲虫装機 · 2012"],"wind-up-2012":["Wind-Up · 2012","ゼンマイ · 2012"],"mermail-atlantean-2012":["Mermail Atlantean · 2012","水精鱗海皇 · 2012"],"dragon-ruler-2013":["Dragon Ruler Inferno · 2013","征竜・烈火 · 2013"],"spellbook-2013":["Spellbook Judgment · 2013","魔導書・神判 · 2013"],"evilswarm-2013":["Evilswarm Pandemic · 2013","ヴェルズ・疫病 · 2013"],"fire-fist-2013":["Fire Fist Four-Axis · 2013","炎星・四軸 · 2013"],"bujin-2013":["Bujin Descent · 2013","武神降臨 · 2013"],"shaddoll-2014":["Shaddoll Weave · 2014","影依の織り手 · 2014"],"qliphort-2014":["Qliphort Reboot · 2014","クリフォート再起動 · 2014"],"nekroz-2014":["Nekroz Ascension · 2014","影霊衣降臨 · 2014"]},descriptions={"blackwing-2009":["Black Whirlwind searches, Kalut protects battles, and Blizzard enables Synchro plays. Inspired by the 2009 world champion.","黒い旋風でサーチし、カルートで戦闘を支援。ブリザードからシンクロへ。2009年世界王者の戦術を参考にした構築。"],"cat-gladiator-2009":["Rescue Cat supports Gladiator Beast tag-outs and Contact Fusion. Inspired by the 2009 runner-up.","レスキューキャットから剣闘獣を展開し、戦闘後の交代とコンタクト融合へ。2009年世界準優勝の戦術が基礎。"],"cat-synchro-2009":["A popular 2009 alternative: Summoner Monk, Rescue Cat and Flamvell build flexible Synchro combinations.","2009年に活躍した猫シンクロ。サモンプリースト、レスキューキャット、フレムベルでレベルを組み合わせる。"],"frog-ftk-2010":["Inspired by the 2010 champion: Swap Frog, Substitoad and Ronintoadin recycle resources into Mass Driver damage.","2010年世界王者のガエルを参考に、鬼ガエル、イレカエル、粋カエルをマスドライバーのダメージへつなぐ。"],"blackwing-2010":["The 2010 Blackwing engine adds Zephyros and resource Spells. Draw cards before committing to a Summon route.","2010年のBFにゼピュロスやドロー魔法を採用。特殊召喚を制限する魔法の使用順に注意。"],"herald-2010":["Inspired by the 2010 third-place strategy: exact Ritual Levels and Fairy cards in hand support Herald negation.","2010年世界3位の宣告者を参考にした構築。儀式のレベル合計と手札の天使族で神光の宣告者を支える。"],"agents-2011":["Inspired by the 2011 champion: Earth searches, Venus summons Shine Balls, and Hyperion converts the Graveyard into removal.","2011年世界王者の代行天使。アースでサーチ、ヴィーナスで球体を展開し、ヒュペリオンで墓地を除去に使う。"],"junk-doppel-2011":["Junk Doppel links Tokens and Plant Tuners into Formula Synchron, Hyper Librarian and Shooting Quasar Dragon.","ジャンクドッペル。トークンと植物チューナーからフォーミュラ、ライブラリアン、シューティング・クェーサーへ。"],"six-samurai-2011":["A popular 2011 alternative: Kageki and Kagemusha summon Shi En, while Dojo and United replenish resources.","2011年の代表的な真六武衆。カゲキと影武者からシエンへ。道場と結束で展開を継続。"],"inzektor-2012":["Inspired by the Inzektor-heavy 2012 Worlds: Hornet leaving its host triggers Dragonfly or Centipede; Ladybug changes Levels.","甲虫装機が上位を占めた2012年世界大会が基礎。ホーネットの装備解除からダンセルとセンチピードを展開。"],"wind-up-2012":["A varied 2012 alternative: Shark adjusts Levels, Magician and Rat extend plays, and Zenmaity connects Rank 3 monsters.","2012年を代表するゼンマイ。シャークのレベル調整とマジシャン、ネズミの展開でランク3につなぐ。"],"mermail-atlantean-2012":["A late-2012 WATER strategy. Discard Atlanteans as WATER monster costs, and use Abyss-sphere and Linde to extend plays.","2012年後半の水精鱗海皇。水属性の効果コストで海皇を墓地へ送り、アビスフィアーとリンデで展開を継続。"],"dragon-ruler-2013":["Inspired by 2013 world champion Shin En Huang. Each Dragon Ruler discards itself together with a same-Attribute Dragon to search or revive, then overlays into Number 11: Big Eye and Mecha Phantom Beast Dracossack while Super Rejuvenation turns the hand into advantage.","2013年世界王者Shin En Huangの征竜を参考にした構築。四色の征竜は自身と同属性のドラゴンを捨ててサーチと蘇生を行い、No.11 ビッグ・アイと幻獣機ドラゴサックへ繋ぐ。超再生で手札を循環させる。"],"spellbook-2013":["Inspired by 2013 runner-up David J. Keener III. Spellbook of Judgment stacks same-name Spells and searches Prophecy monsters, while High Priestess of Prophecy and The Grand Spellbook Tower recycle everything back into the hand.","2013年世界準優勝David J. Keener IIIの魔導書を参考にした構築。魔導書の神判で同名魔法を積み魔導をサーチし、魔導法士ジュノンと魔導書院ラメイソンで資源を回収する。"],"evilswarm-2013":["Third most successful 2013 OCG archetype and the most stable non-Dragon-Ruler, non-Spellbook system; chosen by the popularity rule because the championship podium was homogeneous. Rescue Rabbit assembles the Level 4 Evilswarm, and Evilswarm Ophion locks high-Level Special Summons out of the game.","2013年OCGで上位3番目、征竜と魔導書以外では最も安定した入魔。表彰台が同質化したため人気基準で選出。レスキューラビットでヴェルズを並べ、ヴェルズ・オピオンで高レベル特殊召喚を封じる。"],"fire-fist-2013":["A 2013 OCG build of Four-Axis Fire Fist, ranked 4th in both of the year’s metagame reports. Tenki searches the Beast-Warriors, Tensu grants the extra Normal Summon, and Tiger King Sets a Fire Formation on arrival and negates opposing face-up Effect Monsters each turn.","2013年のOCG上位で第4位だった4軸炎星。天璣で獣戦士をサーチし、天枢で通常召喚を追加。タイガー・キングはエクシーズ召喚時に炎舞をセットし、毎ターン相手の表側効果モンスターを無効化する。"],"bujin-2013":["A representative build of Bujin, the 2013 debut archetype. The Bujingi pay for themselves from the hand or Graveyard and rewrite combat: Crane doubles a Bujin’s original ATK, Turtle banishes itself to stop a targeting effect. Yamato searches another Bujin each End Phase.","2013年に登場した武神の代表的な構築。武神器は手札や墓地から自身を消費して戦闘結果を書き換える。ヤマトは毎ターンのエンドフェイズに武神をサーチし、4軸でスサノオとカグツチを重ねる。"],"shaddoll-2014":["An adaptation of the third most represented strategy in the 2014 year-end OCG report. Fusion materials trigger graveyard effects.","2014年末OCG上位分布3位のシャドールを参考にした構築。融合素材の墓地効果で展開する。"],"qliphort-2014":["An adaptation of the second most represented strategy in the 2014 year-end OCG report. Scout searches, Pendulum Summons supply Tributes.","2014年末OCG上位分布2位のクリフォートを参考にした構築。ツールでサーチし、ペンデュラム召喚からアドバンス召喚へ。"],"nekroz-2014":["An adaptation of the most represented strategy in the 2014 year-end OCG report. Ritual searches and Kaleidoscope turn the Extra Deck into resources.","2014年末OCG上位分布1位の影霊衣を参考にした構築。儀式サーチと万華鏡によるエクストラデッキ活用。"]};for(const [id,labels] of Object.entries(names)){ui.deckNames[id]=labels;ui.deckDescriptions[id]=descriptions[id];const d=root.DuelData.DECKS[id];ui.messages[d.player]={en:labels[0].split(' · ')[0],ja:labels[1].split(' · ')[0]};ui.messages[d.mechanic]={en:labels[0].replace(' · ',' / '),ja:labels[1].replace(' · ',' / ')};}const chronicle=root.DuelData.families.early,lastYear=Math.max(...root.DuelData.earlyYears);ui.messages[chronicle]={en:'Card Chronicle · 1999–'+lastYear,ja:'カード年代記 · 1999–'+lastYear};})(globalThis);
